const pAll=ch=>{const tot=TASKS.reduce((a,t)=>a+t.sub.length,0);const don=TASKS.reduce((a,t)=>a+t.sub.filter((_,i)=>ch[`${t.id}_${i}`]).length,0);return{d:don,t:tot,p:tot?Math.round(don/tot*100):0};};
