// Animated number counter
function AnimNum({value,color,style={},suffix=""}) {
  const [disp,setDisp]=useState(value);
  useEffect(()=>{
    let start=null,from=disp,to=value;
    if(from===to) return;
    const step=ts=>{
      if(!start)start=ts;
      const prog=Math.min((ts-start)/400,1);
      setDisp(Math.round(from+(to-from)*prog));
      if(prog<1)requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  },[value]);
  return <span style={{...style,color}}>{disp}{suffix}</span>;
}

// Ring with canvas particles
function Ring({p,size=44,sw=3,acc=C.warm}) {
  const r=(size-sw)/2,circ=2*Math.PI*r,off=circ*(1-p/100);
  const endAngle=(-Math.PI/2)+(p/100)*2*Math.PI;
  const ex=size/2+r*Math.cos(endAngle),ey=size/2+r*Math.sin(endAngle);
  return <div style={{position:"relative",width:size,height:size,flexShrink:0}}>
    <svg width={size} height={size} style={{position:"absolute",inset:0,transform:"rotate(-90deg)"}}>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={C.border2} strokeWidth={sw}/>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={p===100?"#FFFFFF":acc} strokeWidth={sw}
        strokeDasharray={circ} strokeDashoffset={off} strokeLinecap="round"
        style={{transition:"stroke-dashoffset 1.2s cubic-bezier(.34,1.56,.64,1)",filter:`drop-shadow(0 0 4px ${acc}88)`}}/>
      {p>0&&p<100&&<circle cx={ex} cy={ey} r={sw*0.8} fill={acc}
        style={{filter:`drop-shadow(0 0 6px ${acc})`}}/>}
      {p===100&&<circle cx={ex} cy={ey} r={sw*1.2} fill="#fff"
        style={{filter:"drop-shadow(0 0 8px #fff)"}}/>}
    </svg>
    <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center"}}>
      <span style={{fontSize:size*.18,fontWeight:700,fontFamily:"monospace",color:p===100?"#fff":C.text2}}>{p}%</span>
    </div>
  </div>;
}

// 3D tilt card
function TiltCard({children,style={},onClick}) {
  const handleMove=e=>{
    const el=e.currentTarget;
    const rect=el.getBoundingClientRect();
    const x=((e.clientX-rect.left)/rect.width-.5)*12;
    const y=((e.clientY-rect.top)/rect.height-.5)*-12;
    el.style.transform=`perspective(600px) rotateX(${y}deg) rotateY(${x}deg) translateZ(4px)`;
    el.style.boxShadow=`${-x*.4}px ${y*.4}px 24px rgba(0,0,0,.6)`;
  };
  const handleLeave=e=>{
    e.currentTarget.style.transform="perspective(600px) rotateX(0) rotateY(0) translateZ(0)";
    e.currentTarget.style.boxShadow="";
  };
  return <div className="tilt-card" style={style}
    onMouseMove={handleMove} onMouseLeave={handleLeave} onClick={onClick}>
    {children}
  </div>;
}

// ECG/heartbeat line chart
function ECGChart({data,acc=C.warm,height=80}) {
  if(!data||data.length<2) return null;
  const w=500,h=height,pad=12;
  const vals=data.map(d=>d.value||0);
  const max=Math.max(...vals,1);
  const pts=data.map((d,i)=>{
    const x=pad+(i/(data.length-1))*(w-pad*2);
    const y=h-pad-(d.value/max)*(h-pad*2);
    return [x,y];
  });
  let path=`M${pts[0][0]},${h-pad}`;
  pts.forEach(([x,y],i)=>{
    if(i===0)return;
    const prev=pts[i-1];
    const mx=(prev[0]+x)/2;
    path+=` L${mx-3},${h-pad} L${mx},${y-6} L${mx+3},${y} L${x},${y}`;
  });
  const fillPath=path+` L${pts[pts.length-1][0]},${h-pad} Z`;
  return <svg viewBox={`0 0 ${w} ${h}`} style={{width:"100%",height,overflow:"visible"}} preserveAspectRatio="none">
    <defs>
      <linearGradient id="ecgfill" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={acc} stopOpacity=".25"/>
        <stop offset="100%" stopColor={acc} stopOpacity="0"/>
      </linearGradient>
    </defs>
    <path d={fillPath} fill="url(#ecgfill)" opacity=".6"/>
    <path d={path} fill="none" stroke={acc} strokeWidth="1.5"
      style={{filter:`drop-shadow(0 0 3px ${acc}88)`}}/>
    {pts.map(([x,y],i)=>data[i]?.accepted&&
      <circle key={i} cx={x} cy={y} r={3} fill={acc}
        style={{filter:`drop-shadow(0 0 5px ${acc})`}}/>
    )}
    <circle cx={pts[pts.length-1][0]} cy={pts[pts.length-1][1]} r={4} fill={acc}
      style={{animation:"pulse 1.5s infinite",filter:`drop-shadow(0 0 6px ${acc})`}}/>
  </svg>;
}

// Cinematic sprint acceptance overlay
function CinematicAccept({show,amount,onDone}) {
  const [phase,setPhase]=useState(0);
  useEffect(()=>{
    if(!show){setPhase(0);return;}
    setPhase(1);
    const t1=setTimeout(()=>setPhase(2),350);
    const t2=setTimeout(()=>setPhase(3),850);
    const t3=setTimeout(()=>{setPhase(0);onDone?.();},3500);
    return()=>{clearTimeout(t1);clearTimeout(t2);clearTimeout(t3);};
  },[show]);
  if(!show&&phase===0) return null;
  return <>
    {phase>=1&&<div className="cinematic-flash"/>}
    {phase>=2&&<div className="cinematic-overlay" style={{animation:"apr .3s ease"}}>
      <svg className="cinematic-ring" width={140} height={140} style={{marginBottom:16}}>
        <circle cx={70} cy={70} r={50} fill="none" stroke={C.border2} strokeWidth={3}/>
        <circle cx={70} cy={70} r={50} fill="none" stroke={C.green} strokeWidth={3}
          strokeLinecap="round" style={{transformOrigin:"70px 70px",transform:"rotate(-90deg)",
          animation:"cinematic-ring 1s ease-out forwards",strokeDasharray:314,strokeDashoffset:314,
          filter:"drop-shadow(0 0 10px #A3E635)"}}/>
        {phase>=3&&<polyline points="48,70 62,84 92,56" fill="none" stroke="#fff" strokeWidth={4}
          className="cinematic-check" strokeLinecap="round" strokeLinejoin="round"/>}
      </svg>
      {phase>=3&&<>
        <div style={{fontSize:13,color:C.text3,letterSpacing:4,marginBottom:6,animation:"apr .3s ease"}}>СПРИНТ ПРИНЯТ</div>
        <div className="cinematic-amount" style={{fontSize:36,fontWeight:900,color:C.warm,letterSpacing:2,fontFamily:"monospace",
          textShadow:`0 0 30px ${C.warm}`}}>+{amount}</div>
        <div style={{marginTop:12,fontSize:9,color:C.text3,letterSpacing:3,animation:"apr .3s ease .3s both"}}>ВЫПЛАТА ПОДТВЕРЖДЕНА</div>
      </>}
    </div>}
  </>;
}

// Boot sequence with katakana
function BootSequence({onDone}) {
  const lines=[
    "ARASAKA BUSINESS INC.",
    "荒坂コーポレーション",
    "MOSCOW CITY DIVISION · ВОЕВОДА SYS",
    "",
    "VOEVODA CONTROL SYSTEM v207",
    "",
    "ИНИЦИАЛИЗАЦИЯ ЯДРА...",
    "ЗАГРУЗКА БАЗЫ ДАННЫХ...",
    "ВЕРИФИКАЦИЯ ПРОТОКОЛОВ...",
    "СИНХРОНИЗАЦИЯ КОМАНДЫ...",
    "",
    "СИСТЕМА ГОТОВА. ИДЕНТИФИЦИРУЙТЕСЬ."
  ];
  const [shown,setShown]=useState(0);
  const [done,setDone]=useState(false);
  useEffect(()=>{
    if(shown<lines.length){
      const t=setTimeout(()=>setShown(s=>s+1),shown===0?300:shown===1?200:150);
      return()=>clearTimeout(t);
    } else {
      const t=setTimeout(()=>setDone(true),300);
      const t2=setTimeout(()=>onDone?.(),700);
      return()=>{clearTimeout(t);clearTimeout(t2);};
    }
  },[shown,lines.length]);
  return <div className="boot-overlay" style={{opacity:done?0:1,transition:"opacity .4s",pointerEvents:done?"none":"all"}}>
    <div className="boot-logo">ARASAKA</div>
    <div style={{textAlign:"center",minHeight:200,display:"flex",flexDirection:"column",gap:4,justifyContent:"flex-start"}}>
      {lines.slice(0,shown).map((l,i)=><div key={i} className="boot-line" style={{
        animationDelay:`${i*10}ms`,
        color:i===0?"#FFFFFF":i===1?`rgba(124,58,237,.65)`:i===2?"#A0A0A0":i===4?"#7C3AED":l===""?"transparent":i===11?"#A3E635":"#A3E635",
        fontSize:i===0?14:i===1?13:i===2?9:i===4?11:9,
        fontWeight:i===0||i===4?700:400,
        fontFamily:i===1?"serif":"monospace",
        letterSpacing:i===1?3:2
      }}>{l||" "}</div>)}
      {shown<lines.length&&<div className="boot-line" style={{animationDelay:"0ms"}}>
        <span className="boot-cursor"/>
      </div>}
    </div>
  </div>;
}

